// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    DEP_BANK c;
    LogFile logFile;

    function setUp() public {
        c = new DEP_BANK();
        logFile = new LogFile();
        c.SetLogFile(address(logFile));
        c.Initialized();
    }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(depositAmount <= VALUE_CAP);
        address actor = address(0xBEEF);
        depositAmount = bound(depositAmount, 1, 100 ether);
        collectAmount = bound(collectAmount, 1, depositAmount);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(actor);

        vm.prank(actor);
        bool ok;
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = c.balances(actor);

        // Since Log is set and has code, Collect reaches the call to msg.sender (actor, an EOA with no code);
        // the call succeeds, so the reference allows the collection and the mutant does too.
        // The key invariant is that any failed transfer must leave balances unchanged; this test's EOA actor
        // cannot make the call fail, so it passes on both. To distinguish the mutant we need a failing callee.
        // We deploy a Reverter and make actor be the Reverter, so the transfer always fails.
        // Re-run the scenario with actor = Reverter to expose the bug.
        Reverter reverter = new Reverter();
        address failingActor = address(reverter);
        vm.deal(failingActor, depositAmount);
        vm.prank(failingActor);
        c.Deposit{value: depositAmount}();

        uint256 failingBalanceBefore = c.balances(failingActor);

        vm.prank(failingActor);
        bool failingOk;
        try c.Collect(collectAmount) {
            failingOk = true;
        } catch {
            failingOk = false;
        }

        uint256 failingBalanceAfter = c.balances(failingActor);

        // On the reference, when the external call fails, Collect reverts, so the balance must be unchanged.
        // On the mutant, the revert is omitted, so the balance is reduced despite a failed transfer.
        assertTrue(failingBalanceAfter == failingBalanceBefore);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
    receive() external payable {
        revert();
    }
}
